    }

    override fun read(buf: ByteBuffer): UdpSocket {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: UdpSocket) = 8UL

    override fun write(value: UdpSocket, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



