    val `status`: kotlin.UShort
    , 
    val `headers`: List<Header>
    , 
    val `url`: kotlin.String
    , 
    val `body`: kotlin.ByteArray
    , 
    /**
     * The body's size when it went to [`HttpRequest::download_to`].
     */
