/**
 * What a calendar day is.
 */
sealed class CalendarKind {
    
    /**
     * Classes as usual; `title` names any event on the day.
     */
    object Instructional : CalendarKind()
    
    
    /**
     * Classes on a day that is usually off, or on another weekday's
     * timetable: `follows` is that weekday (0 = Monday) when VTOP names it.
     */
    data class WorkingDay(
        val `follows`: kotlin.Int?) : CalendarKind()
        
    {
        

        companion object
    }
    
    /**
     * A class day whose labs are the lab exam; theory classes meet.
     */
    object LabFat : CalendarKind()
    
    
    object Holiday : CalendarKind()
    
    
    object NoInstructional : CalendarKind()
    
    
    /**
     * "CAT-I", "CAT-II", "FAT".
     */
    data class Exam(
        val `name`: kotlin.String) : CalendarKind()
        
    {
        

        companion object
    }
    
    /**
     * Something the app does not know; no classes.
     */
    object Other : CalendarKind()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCalendarKind : FfiConverterRustBuffer<CalendarKind>{
    override fun read(buf: ByteBuffer): CalendarKind {
        return when(buf.getInt()) {
            1 -> CalendarKind.Instructional
            2 -> CalendarKind.WorkingDay(
                FfiConverterOptionalInt.read(buf),
                )
            3 -> CalendarKind.LabFat
            4 -> CalendarKind.Holiday
            5 -> CalendarKind.NoInstructional
            6 -> CalendarKind.Exam(
                FfiConverterString.read(buf),
                )
            7 -> CalendarKind.Other
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CalendarKind): ULong = when(value) {
        is CalendarKind.Instructional -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CalendarKind.WorkingDay -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalInt.allocationSize(value.`follows`)
            )
        }
        is CalendarKind.LabFat -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CalendarKind.Holiday -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CalendarKind.NoInstructional -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CalendarKind.Exam -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
        is CalendarKind.Other -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: CalendarKind, buf: ByteBuffer) {
        when(value) {
            is CalendarKind.Instructional -> {
                buf.putInt(1)
                Unit
            }
            is CalendarKind.WorkingDay -> {
                buf.putInt(2)
                FfiConverterOptionalInt.write(value.`follows`, buf)
                Unit
            }
            is CalendarKind.LabFat -> {
                buf.putInt(3)
                Unit
            }
            is CalendarKind.Holiday -> {
                buf.putInt(4)
                Unit
            }
            is CalendarKind.NoInstructional -> {
                buf.putInt(5)
                Unit
            }
            is CalendarKind.Exam -> {
                buf.putInt(6)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
            is CalendarKind.Other -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






