/**
 * Why a call failed. The text field is `reason`, not `message`: Kotlin
 * exceptions already have a `message` and UniFFI would declare it twice.
 */
sealed class CoreException: kotlin.Exception() {
    
    class Offline(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class VtopUnavailable(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InvalidCredentials(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A re-login during a fetch wants the emailed OTP, mailed at `issued_at` (unix seconds;
     * None when unknown).
     */
    class OtpRequired(
        
        val `reason`: kotlin.String, 
        
        val `issuedAt`: kotlin.ULong?
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }, issuedAt=${ `issuedAt` }"
    }
    
    /**
     * `submit_otp` got a wrong or expired code; VTOP's text.
     */
    class OtpRejected(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NotSignedIn(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * No semester picked yet (or VTOP no longer lists the pick): the
     * student picks one from [`Core::fetch_semesters`] first.
     */
    class SemesterNeeded(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The student said no (or wasn't there to ask): the VTOP session stayed on the phone.
     */
    class ConsentDenied(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The student hasn't let this install share their registration number with the server
     * (`remote/regno.rs`): no server identity is taken.
     */
    class RegnoNotShared(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * This phone has no forwarding address, or the server deleted it: an OTP wait on it ends.
     */
    class ForwardingOff(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Other(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Offline()
            2 -> CoreException.VtopUnavailable(
                FfiConverterString.read(buf),
                )
            3 -> CoreException.InvalidCredentials()
            4 -> CoreException.OtpRequired(
                FfiConverterString.read(buf),
                FfiConverterOptionalULong.read(buf),
                )
            5 -> CoreException.OtpRejected(
                FfiConverterString.read(buf),
                )
            6 -> CoreException.NotSignedIn()
            7 -> CoreException.SemesterNeeded()
            8 -> CoreException.ConsentDenied()
            9 -> CoreException.RegnoNotShared()
            10 -> CoreException.ForwardingOff(
                FfiConverterString.read(buf),
                )
            11 -> CoreException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Offline -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.VtopUnavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is CoreException.InvalidCredentials -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.OtpRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
                + FfiConverterOptionalULong.allocationSize(value.`issuedAt`)
            )
            is CoreException.OtpRejected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is CoreException.NotSignedIn -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.SemesterNeeded -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.ConsentDenied -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.RegnoNotShared -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.ForwardingOff -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is CoreException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Offline -> {
                buf.putInt(1)
                Unit
            }
            is CoreException.VtopUnavailable -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is CoreException.InvalidCredentials -> {
                buf.putInt(3)
                Unit
            }
            is CoreException.OtpRequired -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                FfiConverterOptionalULong.write(value.`issuedAt`, buf)
                Unit
            }
            is CoreException.OtpRejected -> {
                buf.putInt(5)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is CoreException.NotSignedIn -> {
                buf.putInt(6)
                Unit
            }
            is CoreException.SemesterNeeded -> {
                buf.putInt(7)
                Unit
            }
            is CoreException.ConsentDenied -> {
                buf.putInt(8)
                Unit
            }
